const pruna = (model)=>{
    let snippets;
    if (model.tags.includes("diffusers")) {
        snippets = pruna_diffusers(model);
    } else if (model.tags.includes("transformers")) {
        snippets = pruna_transformers(model);
    } else {
        snippets = pruna_default(model);
    }
    const ensurePrunaModelImport = (snippet)=>{
        if (!/^from pruna import PrunaModel/m.test(snippet)) {
            return `from pruna import PrunaModel\n${snippet}`;
        }
        return snippet;
    };
    snippets = snippets.map(ensurePrunaModelImport);
    if (model.tags.includes("pruna_pro-ai")) {
        return snippets.map((snippet)=>snippet.replace(/\bpruna\b/g, "pruna_pro").replace(/\bPrunaModel\b/g, "PrunaProModel"));
    }
    return snippets;
};
const pruna_diffusers = (model)=>{
    const diffusersSnippets = diffusers(model);
    return diffusersSnippets.map((snippet)=>snippet// Replace pipeline classes with PrunaModel
        .replace(/\b\w*Pipeline\w*\b/g, "PrunaModel")// Clean up diffusers imports containing PrunaModel
        .replace(/from diffusers import ([^,\n]*PrunaModel[^,\n]*)/g, "").replace(/from diffusers import ([^,\n]+),?\s*([^,\n]*PrunaModel[^,\n]*)/g, "from diffusers import $1").replace(/from diffusers import\s*(\n|$)/g, "")// Fix PrunaModel imports
        .replace(/from diffusers import PrunaModel/g, "from pruna import PrunaModel").replace(/from diffusers import ([^,\n]+), PrunaModel/g, "from diffusers import $1").replace(/from diffusers import PrunaModel, ([^,\n]+)/g, "from diffusers import $1")// Clean up whitespace
        .replace(/\n\n+/g, "\n").trim());
};
const pruna_transformers = (model)=>{
    const auto_model = autoModelClass(model);
    const transformersSnippets = transformers(model);
    // Replace pipeline with PrunaModel
    let processedSnippets = transformersSnippets.map((snippet)=>snippet.replace(/from transformers import pipeline/g, "from pruna import PrunaModel").replace(/pipeline\([^)]*\)/g, `PrunaModel.from_pretrained("${model.id}")`));
    // Additional cleanup if auto_model info is available
    if (auto_model) {
        processedSnippets = processedSnippets.map((snippet)=>snippet.replace(new RegExp(`from transformers import ${auto_model}\n?`, "g"), "").replace(new RegExp(`${auto_model}.from_pretrained`, "g"), "PrunaModel.from_pretrained").replace(new RegExp(`^.*from.*import.*(, *${auto_model})+.*$`, "gm"), (line)=>line.replace(new RegExp(`, *${auto_model}`, "g"), "")));
    }
    return processedSnippets;
};
